import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Grok Build Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-glossary.md","filePath":"products/ai-coding/grok/grok-glossary.md","lastUpdated":1787107158000}'),s={name:"products/ai-coding/grok/grok-glossary.md"};function i(n,e,d,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="grok-build-glossary" tabindex="-1">Grok Build Glossary <a class="header-anchor" href="#grok-build-glossary" aria-label="Permalink to &quot;Grok Build Glossary&quot;">​</a></h1><p>Concepts, not commands. Read this when something in Grok Build seems arbitrary — usually there is a reason, and it is usually about safety boundaries or context economy.</p><h2 id="things-called-grok" tabindex="-1">Things called Grok <a class="header-anchor" href="#things-called-grok" aria-label="Permalink to &quot;Things called Grok&quot;">​</a></h2><p>The name collides constantly. Sorting it out first saves a lot of confusion:</p><table tabindex="0"><thead><tr><th>Name</th><th>What it actually is</th></tr></thead><tbody><tr><td><strong>Grok Build</strong></td><td>The terminal coding agent — the subject of these docs. Executable <code>grok</code>. Docs live under <code>docs.x.ai/build/*</code>.</td></tr><tr><td><a href="./grok-chat.html">Grok (the chat product)</a></td><td>The general-purpose assistant on <a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a>, the Grok apps, and inside X. Chat, search, voice, files.</td></tr><tr><td><a href="./grok-imagine.html">Imagine</a></td><td>Image and video generation / editing. Consumer entry: <a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a>. Programmatic entry: the <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">Imagine API</a>.</td></tr><tr><td><a href="./grok-voice.html">Voice</a></td><td>Two boxes: <strong>product</strong> Voice (&quot;Talk to Grok hands-free&quot;) on grok.com / apps, and the <strong>Voice API</strong> (TTS / STT / Speech to Speech).</td></tr><tr><td><a href="./grok-connectors.html">Connectors</a></td><td>Chat-side links to email, files, calendar, catalog OAuth, or a public MCP server. Not Grok Build <code>grok mcp add</code>.</td></tr><tr><td>Build Mode</td><td>A grok.com / Grok-app <strong>chat mode</strong> (mode switcher → <strong>Build</strong>). Early Beta for SuperGrok Heavy on web, iOS, and Android (<a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>, <a href="https://x.ai/news/grok-build-mode" target="_blank" rel="noreferrer">news</a>). &quot;Tell Grok an idea, and it builds a working version live in your chat.&quot; Publish to grok.me or a custom domain. Websites, apps, games, dashboards (dashboards can use Connectors). Nothing to install. <strong>Not</strong> Grok Build. Official density is a marketing page + one news post, so no standalone tutorial.</td></tr><tr><td>grok.me</td><td>The <strong>publish host</strong> for Build Mode (&quot;Publish to a grok.me link or a custom domain you own&quot;). Not a product, not the CLI.</td></tr><tr><td><a href="./grok-bot.html">Grok Bot</a></td><td>Named AI teammates on one persistent cloud computer. Desktop + iOS. Docs: <a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot</a>. <strong>Not</strong> Grok Build headless.</td></tr><tr><td><a href="./grok-business.html">Grok Business</a></td><td>Team workspaces, SuperGrok / SuperGrok Heavy licenses, org sharing. Docs: <a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a>.</td></tr><tr><td><code>grok-4.6</code></td><td>A model. The one currently driving Grok Build.</td></tr><tr><td><code>grok-build-0.1</code></td><td>A different model, trained specifically for agentic coding. Cheaper, smaller context.</td></tr><tr><td>xAI API</td><td>The model API at <code>api.x.ai</code>. Grok Build is a <em>client</em> of it, not the same thing.</td></tr></tbody></table><p><strong>Not official names or products (do not write them as facts):</strong></p><ul><li>&quot;Grok Code&quot; and &quot;Grok CLI&quot; — the official product name is Grok Build; the binary is <code>grok</code>; the repo is <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">xai-org/grok-build</a>.</li><li>An official VS Code / JetBrains plugin — editor integration is ACP (<code>grok agent stdio</code>).</li><li>grok.me as a separate &quot;Build product&quot; — it is only the publish URL for Build Mode.</li><li>Third-party posts about &quot;Grok 4.3&quot;, &quot;2 million token context&quot;, &quot;Arena Mode&quot;, or &quot;8 parallel agents&quot; as product specs — this set only records slugs and limits that appear on <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">docs.x.ai</a> or <a href="https://x.ai" target="_blank" rel="noreferrer">x.ai</a>.</li></ul><p>The decision tree for picking a surface is on the <a href="./">learning map</a>. Product maps: <a href="./grok-chat.html">Chat</a>, <a href="./grok-imagine.html">Imagine</a>, <a href="./grok-voice.html">Voice</a>, <a href="./grok-connectors.html">Connectors</a>, <a href="./grok-bot.html">Grok Bot</a>, <a href="./grok-business.html">Business</a>.</p><h2 id="one-agent-three-faces" tabindex="-1">One agent, three faces <a class="header-anchor" href="#one-agent-three-faces" aria-label="Permalink to &quot;One agent, three faces&quot;">​</a></h2><p>Grok Build is a single agent exposed through three surfaces, not three products:</p><ul><li><strong>TUI</strong> (<code>grok</code>) — a full-screen terminal UI. Human in the loop.</li><li><strong>Headless</strong> (<code>grok -p &quot;...&quot;</code>) — one prompt, structured output, exit. No human.</li><li><strong>ACP</strong> (<code>grok agent stdio</code>) — JSON-RPC over stdin/stdout so a host application drives it.</li></ul><p>They share sessions, configuration, permission rules, hooks, and MCP servers. A session started in the TUI can be resumed headlessly and vice versa, because sessions are stored on disk under <code>~/.grok/sessions/</code>, keyed by working directory.</p><p>The practical consequence: there is no &quot;IDE version&quot; to learn. Editor integration means an editor speaking ACP to the same binary.</p><h2 id="permissions-and-the-sandbox-are-two-orthogonal-axes" tabindex="-1">Permissions and the sandbox are two orthogonal axes <a class="header-anchor" href="#permissions-and-the-sandbox-are-two-orthogonal-axes" aria-label="Permalink to &quot;Permissions and the sandbox are two orthogonal axes&quot;">​</a></h2><p>The single most common misunderstanding. xAI states it plainly:</p><blockquote><p>Permissions decide which tool calls may run. The sandbox is separate: it limits what an approved call can do on the filesystem and network.</p></blockquote><p>Think of it as two gates in series:</p><ol><li><strong>Permission gate</strong> — may this tool call happen at all? Answered by <code>allow</code> / <code>ask</code> / <code>deny</code> rules and the current permission mode.</li><li><strong>Sandbox</strong> — now that it is running, what can it reach? Answered by the OS (Landlock on Linux, Seatbelt on macOS).</li></ol><p>Always-approve mode opens the first gate wide. It does <strong>not</strong> touch the second. That is why <code>grok --always-approve --sandbox read-only</code> is a coherent combination and a genuinely useful one: let the agent work uninterrupted, but make it physically unable to write.</p><p>Conversely, a permissive sandbox with strict <code>deny</code> rules is the opposite trade: the agent asks less often about safe things but is hard-blocked on the patterns you named.</p><p>The sandbox is off by default, so out of the box you only have the first gate.</p><h2 id="five-config-layers-why-the-highest-priority-lives-in-etc" tabindex="-1">Five config layers: why the highest priority lives in /etc <a class="header-anchor" href="#five-config-layers-why-the-highest-priority-lives-in-etc" aria-label="Permalink to &quot;Five config layers: why the highest priority lives in /etc&quot;">​</a></h2><p>Configuration precedence runs, from lowest to highest:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Path</th><th>Who controls it</th></tr></thead><tbody><tr><td>1</td><td><code>/etc/grok/managed_config.toml</code></td><td>Admin — <strong>defaults</strong></td></tr><tr><td>2</td><td><code>~/.grok/managed_config.toml</code></td><td>MDM-delivered user defaults</td></tr><tr><td>3</td><td><code>~/.grok/config.toml</code></td><td>The user</td></tr><tr><td>4</td><td><code>~/.grok/requirements.toml</code></td><td>User-level hard requirements</td></tr><tr><td>5</td><td><code>/etc/grok/requirements.toml</code></td><td>Admin — <strong>mandates</strong></td></tr></tbody></table><p>Note the shape: the admin appears twice, at the bottom <em>and</em> the top. <code>managed_config.toml</code> sets defaults the user may override; <code>requirements.toml</code> sets constraints the user may not. That is why &quot;managed&quot; and &quot;required&quot; are separate files rather than one file with a priority flag — they express different intents.</p><p>One detail that turns this from theory into practice: the tamper-resistance lock is honored <strong>only when the source file is root-owned</strong>. Writing <code>disable_bypass_permissions_mode = true</code> into a user-writable <code>~/.grok/requirements.toml</code> is not a lock, because whoever wrote it can also delete it.</p><p>A project-level <code>.grok/config.toml</code> is deliberately not in this ladder. It only supports <code>[mcp_servers]</code>, <code>[plugins]</code>, and <code>[permission]</code>. A repository you clone cannot change your default permission mode, your model, or your sandbox profile. That restriction is the security property, not an oversight.</p><h2 id="authentication-four-paths-and-one-resolution-order" tabindex="-1">Authentication: four paths and one resolution order <a class="header-anchor" href="#authentication-four-paths-and-one-resolution-order" aria-label="Permalink to &quot;Authentication: four paths and one resolution order&quot;">​</a></h2><p>Four ways in — browser OIDC, device code, API key, external auth provider — but only one order of resolution:</p><p><code>model.api_key</code> &gt; <code>model.env_key</code> &gt; active session token &gt; <code>XAI_API_KEY</code></p><p>Read it as &quot;most specific wins&quot;. A per-model key beats an environment variable, which is what you want when one model in your config points at a third-party endpoint: that model&#39;s key should not be shadowed by the global <code>XAI_API_KEY</code>.</p><p>The order also explains a confusing symptom. If you <code>grok login</code> and <em>also</em> export <code>XAI_API_KEY</code>, the session token wins, and usage lands on your subscription rather than your API credit. Which is usually right, and occasionally surprising.</p><h2 id="agents-md-why-deeper-files-win" tabindex="-1">AGENTS.md: why deeper files win <a class="header-anchor" href="#agents-md-why-deeper-files-win" aria-label="Permalink to &quot;AGENTS.md: why deeper files win&quot;">​</a></h2><p>Rules load global-first, then from the repository root downward to the current directory. Later files take precedence, so the deepest <code>AGENTS.md</code> wins.</p><p>This is the inverse of how CSS specificity feels but the same as how you&#39;d reason about it in person: repository-wide conventions are the backdrop, and the conventions of the specific package you are standing in are the foreground. <code>packages/legacy-widget/AGENTS.md</code> saying &quot;this directory is CommonJS, do not convert it&quot; must beat the root file saying &quot;we use ESM&quot;.</p><p>Grok Build also reads the Claude family (<code>CLAUDE.md</code>, <code>CLAUDE.local.md</code>, <code>.claude/rules/</code>) and Cursor&#39;s <code>.cursor/rules/</code> in the same walk. Gitignored files are skipped — so a personal <code>CLAUDE.local.md</code> that you gitignored is <em>not</em> loaded, which is worth knowing before you spend an hour wondering why your rule has no effect. <code>grok inspect</code> prints exactly which rules files loaded, with token counts.</p><h2 id="plan-mode-gates-edits-not-the-shell" tabindex="-1">Plan mode gates edits, not the shell <a class="header-anchor" href="#plan-mode-gates-edits-not-the-shell" aria-label="Permalink to &quot;Plan mode gates edits, not the shell&quot;">​</a></h2><p>In plan mode only the session plan file is editable. It sounds like a read-only mode. It is not.</p><p>xAI is explicit that bash can still write through shell redirection. <code>echo x &gt; file.txt</code> is a bash call, not an edit call, and the plan-mode gate is on the edit tools. So plan mode prevents <em>accidental</em> edits and preserves the review step; it is not an isolation boundary.</p><p>If you want an actual boundary, that is what the sandbox is for. This is the same distinction as the two gates above, showing up in a different place.</p><p>Plan mode is also independent of permission mode: always-approve does not skip the plan review screen. The two systems compose rather than override.</p><h2 id="a-session-is-branchable-state-not-a-chat-log" tabindex="-1">A session is branchable state, not a chat log <a class="header-anchor" href="#a-session-is-branchable-state-not-a-chat-log" aria-label="Permalink to &quot;A session is branchable state, not a chat log&quot;">​</a></h2><p>Four operations make sense only if you stop thinking of a session as a transcript:</p><ul><li><strong>fork</strong> (<code>/fork</code>) — branch the conversation. Optionally <code>--worktree</code>, which branches the <em>files</em> too. Two agents, two states, from a shared prefix.</li><li><strong>rewind</strong> (<code>/rewind</code>, or <code>Esc Esc</code> on an empty input) — roll back to an earlier turn. <strong>This reverts files on disk as well.</strong> It is not &quot;delete the last message&quot;; uncommitted work disappears. Commit first.</li><li><strong>compact</strong> (<code>/compact [focus]</code>) — rewrite history into a summary to reclaim context. Also happens automatically.</li><li><strong>resume</strong> (<code>grok -c</code>, <code>grok -r &lt;id&gt;</code>) — pick a stored state back up, from any of the three surfaces.</li></ul><p>Once files are part of the state, fork plus worktree becomes the natural way to try two approaches to the same problem, and the Agent Dashboard (<code>Ctrl+\\</code>) becomes necessary rather than decorative — you now have several live states to watch.</p><p>Worktree cleanup (<code>grok worktree gc</code>) never runs automatically. Automatic cleanup would eventually delete agent output nobody has reviewed yet, which is a worse failure than leaving stale directories on disk.</p><h2 id="five-extension-mechanisms-and-their-division-of-labor" tabindex="-1">Five extension mechanisms and their division of labor <a class="header-anchor" href="#five-extension-mechanisms-and-their-division-of-labor" aria-label="Permalink to &quot;Five extension mechanisms and their division of labor&quot;">​</a></h2><p>They overlap enough to be confusing, so here is what each one actually changes:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Changes</th><th>Lives in</th></tr></thead><tbody><tr><td><strong>Skill</strong></td><td>Knowledge and procedure — <em>how</em> to do a thing</td><td><code>~/.grok/skills/</code>, <code>./.grok/skills/</code></td></tr><tr><td><strong>MCP server</strong></td><td>The tool set — <em>what</em> the agent can call</td><td><code>[mcp_servers]</code> in config</td></tr><tr><td><strong>Plugin</strong></td><td>Distribution — packages skills, commands, agents, hooks, MCP, LSP together</td><td><code>~/.grok/plugins/</code>, <code>./.grok/plugins/</code></td></tr><tr><td><strong>Subagent</strong></td><td>Execution — a separate context window that reports a summary back</td><td><code>~/.grok/agents/</code>, <code>.grok/agents/</code></td></tr><tr><td><strong>Workflow</strong></td><td>Orchestration — <code>.rhai</code> scripts that fan out and aggregate</td><td><code>~/.grok/workflows/*.rhai</code></td></tr><tr><td><strong>Persona</strong></td><td>Behavior — tone, focus, output contract</td><td><code>~/.grok/personas/*.toml</code></td></tr></tbody></table><p>Two misconceptions worth naming:</p><p><strong><code>allowed-tools</code> in a skill&#39;s frontmatter is not permission control.</strong> xAI states that it neither grants nor restricts tools. It is a hint. Real control is <code>[permission]</code> rules, <code>--tools</code>, and <code>--disallowed-tools</code>. Treating a skill&#39;s frontmatter as a security boundary is a mistake with real consequences.</p><p><strong>A persona is not a kind of subagent.</strong> A persona changes how the agent writes; a subagent changes where the work runs and whose context window pays for it. You can apply a persona to a subagent, which is exactly why they are separate concepts.</p><p>Subagents exist for <strong>context economy</strong>. Exploring a large repository produces a lot of intermediate output — file listings, search hits, dead ends — that is pure noise in the main conversation. The <code>explore</code> subagent burns its own context window on that and hands back a conclusion. It is read-only, cannot run shell commands, and cannot edit files, which is what makes it safe to run without supervision.</p><h2 id="why-it-goes-out-of-its-way-to-be-claude-code-compatible" tabindex="-1">Why it goes out of its way to be Claude Code compatible <a class="header-anchor" href="#why-it-goes-out-of-its-way-to-be-claude-code-compatible" aria-label="Permalink to &quot;Why it goes out of its way to be Claude Code compatible&quot;">​</a></h2><p>Grok Build reads <code>CLAUDE.md</code>, <code>.claude/settings.json</code> hooks, Claude skills and agents and MCP configs, accepts Claude Code&#39;s CLI flag names as aliases, and ships <code>grok import</code> for Claude Code sessions. The README&#39;s phrasing: &quot;Grok is fully compatible with Claude Code with zero configuration needed.&quot;</p><p>The strategic reading is obvious — it removes the switching cost for the incumbent&#39;s users. The practical reading matters more to you: <strong>a repository configured for Claude Code is already configured for Grok Build</strong>, which makes a genuine side-by-side comparison cheap. Run both on the same task, same rules, same tools.</p><p>There is one deliberate gap in the compatibility, and it is instructive. Claude&#39;s <code>disableBypassPermissionsMode: &quot;disable&quot;</code> is <em>not</em> applied to Grok&#39;s always-approve mode, and Grok&#39;s own <code>/etc/grok/requirements.toml</code> always takes precedence over Claude&#39;s <code>managed-settings.json</code>. Compatibility extends to convenience, not to security policy — Grok will not let another vendor&#39;s config file decide its safety boundaries.</p><h2 id="why-this-document-will-go-out-of-date" tabindex="-1">Why this document will go out of date <a class="header-anchor" href="#why-this-document-will-go-out-of-date" aria-label="Permalink to &quot;Why this document will go out of date&quot;">​</a></h2><p>Grok Build entered early beta on 2026-05-25. npm <code>@xai-official/grok</code> <code>latest</code> moved 1.0.3 → 1.0.5 between 2026-08-12 and 2026-08-16. External pull requests are not accepted; feedback goes through <code>/feedback</code>.</p><p>So treat every table here as a snapshot, and prefer these habits over memorizing values:</p><ul><li><code>grok --help</code> and <code>grok &lt;subcommand&gt; --help</code> are the authoritative command surface.</li><li><code>grok inspect --json</code> answers &quot;what is actually loaded on this machine&quot; better than any document can.</li><li><a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">x.ai/build/changelog</a> can list commands before <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">CLI Reference</a> does. When behavior does not match documentation, check the changelog first.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Grok learning map</a></li><li><a href="./grok-cli.html">Grok Build tutorial</a></li><li><a href="./grok-cookbook.html">Grok Build cookbook</a></li><li><a href="./grok-cheatsheet.html">Grok Build cheatsheet</a></li><li><a href="./grok-chat.html">Grok Chat</a></li><li><a href="./grok-imagine.html">Imagine</a></li><li><a href="./grok-voice.html">Voice</a></li><li><a href="./grok-connectors.html">Connectors</a></li><li><a href="./grok-bot.html">Grok Bot</a></li><li><a href="./grok-business.html">Grok Business</a></li></ul>',63)])])}const k=o(s,[["render",i]]);export{f as __pageData,k as default};
